import time, anthropic
client = anthropic.Anthropic()

def run(task, tools, handlers, max_steps=15, max_seconds=120, max_tokens_total=60_000):
    messages = [{"role": "user", "content": task}]
    start, used = time.time(), 0
    for step in range(max_steps):
        if time.time() - start > max_seconds or used > max_tokens_total:
            return {"status": "budget_exceeded", "messages": messages}
        r = client.messages.create(model="claude-sonnet-5-5", max_tokens=2048,
                                   tools=tools, messages=messages)
        used += r.usage.input_tokens + r.usage.output_tokens
        messages.append({"role": "assistant", "content": r.content})
        if r.stop_reason != "tool_use":
            return {"status": "done", "messages": messages}
        results = []
        for b in r.content:
            if b.type == "tool_use":
                try:
                    out, err = handlers[b.name](**b.input), False
                except Exception as e:
                    out, err = f"Error: {e}", True   # let the model see and recover
                results.append({"type": "tool_result", "tool_use_id": b.id,
                                "content": str(out)[:8000], "is_error": err})
        messages.append({"role": "user", "content": results})
    return {"status": "max_steps", "messages": messages}

